// Combined Data Merger (v1.0)
// This node simply merges the two parallel data streams (ESI and zKill) 
// into a single object for the final analysis node.

try {
  const allInputs = $input.all();
  let combinedData = {};

  // Loop through inputs and merge them.
  // This handles cases where one branch might fail.
  for (const item of allInputs) {
    combinedData = {
      ...combinedData,
      ...item.json
    };
  }

  // Add a simple integration quality check
  const hasChar = !!(combinedData.character_esi && combinedData.character_esi.corporation_id);
  const hasZkill = !!(combinedData.data && combinedData.data.stats);

  combinedData.data_integration = {
    combined_at: new Date().toISOString(),
    has_character_data: hasChar,
    has_zkill_data: hasZkill,
    integration_quality: (hasChar && hasZkill) ? 'complete' : 'partial'
  };

  if (combinedData.data_integration.integration_quality === 'complete') {
    console.log(`✅ Data combination complete for ${combinedData.character_name}`);
  } else {
    console.warn(`⚠️ Data combination is partial for ${combinedData.character_name}. Has ESI: ${hasChar}, Has zKill: ${hasZkill}`);
  }

  return [{ json: combinedData }];

} catch (error) {
  console.error('❌ Data combination failed:', error.message);
  return [{
    json: {
      ...$input.first().json,
      combination_error: error.message,
      data_integration: {
        combined_at: new Date().toISOString(),
        integration_quality: 'failed',
      },
    },
  }];
}

// Character Pull v2.5 – With Corp/Alliance ESI Fetching
const Redis = require('ioredis');
const axios = require('axios');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

// --- Simple Levenshtein distance (no deps)
function levenshtein(a, b) {
  if (a === b) return 0;
  const m = [];
  for (let i = 0; i <= b.length; i++) m[i] = [i];
  for (let j = 0; j <= a.length; j++) m[0][j] = j;
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      m[i][j] = b[i - 1] === a[j - 1]
        ? m[i - 1][j - 1]
        : Math.min(m[i - 1][j - 1] + 1, m[i][j - 1] + 1, m[i - 1][j] + 1);
    }
  }
  return m[b.length][a.length];
}

try {
  const input = $input.first().json;
  const characterNameInput = input.character_name?.trim();
  if (!characterNameInput) throw new Error('Character name is required in the input.');

  console.log(`🔎 Intel process started for: "${characterNameInput}"`);
  let characterId = null;
  let characterName = characterNameInput;
  let lookupSource = '';

  // --- Step 1: Redis cache check
  const cachedId = await redis.hget('eve:name_to_id', characterName.toLowerCase());
  if (cachedId) {
    characterId = parseInt(cachedId, 10);
    lookupSource = 'Redis Cache';
    console.log(`✅ Cache HIT for "${characterName}" → ID ${characterId}`);
  } else {
    console.log(`- Cache MISS for "${characterName}". Querying ESI...`);
    const esiUrl = 'https://esi.evetech.net/latest/universe/ids/?datasource=tranquility';
    const esiRes = await axios.post(esiUrl, [characterName], {
      headers: { 'User-Agent': 'Alfred EVE Intel Tool', 'Content-Type': 'application/json' },
      validateStatus: s => s === 200 || s === 404
    }).catch(() => ({ data: {} }));

    const chars = esiRes.data.characters || [];
    if (chars.length > 0) {
      const resolved = chars[0];
      characterId = resolved.id;
      characterName = resolved.name;
      lookupSource = 'ESI API (/universe/ids)';
      console.log(`✅ ESI found ID ${characterId} for "${characterName}".`);
      await redis
        .pipeline()
        .hset('eve:name_to_id', characterName.toLowerCase(), String(characterId))
        .hset('eve:id_to_name', String(characterId), characterName)
        .exec();
    } else {
      // --- Step 2: Local fuzzy matching from Redis
      console.log(`⚠️ ESI lookup failed. Attempting local fuzzy match...`);
      const allNames = await redis.hkeys('eve:name_to_id');
      const candidates = allNames
        .map(n => ({ name: n, score: levenshtein(characterName.toLowerCase(), n) }))
        .sort((a, b) => a.score - b.score)
        .slice(0, 5);

      if (candidates.length && candidates[0].score <= Math.max(2, Math.floor(characterName.length * 0.3))) {
        const suggestions = candidates.map(c => c.name);
        throw new Error(JSON.stringify({
          errorType: 'CharacterNotFoundWithLocalSuggestions',
          message: `Character "${characterName}" could not be resolved. Closest matches found in Redis.`,
          suggestions
        }));
      }
      throw new Error(`Character "${characterName}" could not be resolved by ESI or local cache.`);
    }
  }

  // --- Step 3: Fetch character details and history
  const charUrl = `https://esi.evetech.net/latest/characters/${characterId}/?datasource=tranquility`;
  const histUrl = `https://esi.evetech.net/latest/characters/${characterId}/corporationhistory/?datasource=tranquility`;

  const [charRes, histRes] = await Promise.all([
    this.helpers.httpRequest({ url: charUrl, json: true }),
    this.helpers.httpRequest({ url: histUrl, json: true })
  ]);

  const corpId = charRes.corporation_id;
  const allianceId = charRes.alliance_id || null;

  // --- Step 4: Fetch Corporation Details from ESI
  console.log(`📊 Fetching corporation ${corpId} from ESI...`);
  let corpData = { id: corpId };
  try {
    const corpUrl = `https://esi.evetech.net/latest/corporations/${corpId}/?datasource=tranquility`;
    const corpRes = await this.helpers.httpRequest({ url: corpUrl, json: true });
    corpData = {
      id: corpId,
      name: corpRes.name,
      ticker: corpRes.ticker,
      member_count: corpRes.member_count,
      ceo_id: corpRes.ceo_id,
      creator_id: corpRes.creator_id,
      date_founded: corpRes.date_founded,
      description: corpRes.description,
      home_station_id: corpRes.home_station_id,
      tax_rate: corpRes.tax_rate,
      url: corpRes.url
    };
    console.log(`✅ Corporation: ${corpData.name} [${corpData.ticker}]`);
  } catch (corpError) {
    console.warn(`⚠️ Failed to fetch corporation ${corpId}:`, corpError.message);
  }

  // --- Step 5: Fetch Alliance Details from ESI
  let allianceData = {};
  if (allianceId) {
    console.log(`🛡️ Fetching alliance ${allianceId} from ESI...`);
    try {
      const allianceUrl = `https://esi.evetech.net/latest/alliances/${allianceId}/?datasource=tranquility`;
      const allianceRes = await this.helpers.httpRequest({ url: allianceUrl, json: true });
      allianceData = {
        id: allianceId,
        name: allianceRes.name,
        ticker: allianceRes.ticker,
        date_founded: allianceRes.date_founded,
        creator_id: allianceRes.creator_id,
        creator_corporation_id: allianceRes.creator_corporation_id,
        executor_corporation_id: allianceRes.executor_corporation_id
      };
      console.log(`✅ Alliance: ${allianceData.name} [${allianceData.ticker}]`);
    } catch (allianceError) {
      console.warn(`⚠️ Failed to fetch alliance ${allianceId}:`, allianceError.message);
    }
  }

  const output = {
    ...input,
    character_name: characterName,
    character_id: characterId,
    lookup_source: lookupSource,
    character_esi: charRes,
    corporation_esi: corpData,
    alliance_esi: allianceData,
    corporation_history_esi: histRes,
    alliance_id: allianceId
  };

  console.log(`✅ Character ESI intel complete for "${characterName}".`);
  return [{ json: output }];

} catch (error) {
  console.error('❌ Character Pull failed:', error.message);
  let parsed = { message: error.message };
  try { parsed = JSON.parse(error.message); } catch {}
  return [{
    json: {
      ...$input.first().json,
      output: parsed.errorType?.includes('Suggestion') ? 'fuzzy' : 'error',
      character_intel_error: parsed.message || error.message,
      suggested_names: parsed.suggestions || null,
      character_esi: null,
      corporation_esi: null,
      alliance_esi: null
    }
  }];
} finally {
  if (redis.status === 'ready') await redis.quit();
}

// Local Zkill Cache Pull - Resilient Data Fill (V2.4: Corrected Redis Keys + Merged K/L)
const Redis = require('ioredis');
const axios = require('axios');
const redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 10000 });
let lookupSource = 'API_Primary_Local_Fallbacks';

// Define input outside the try block for scope access
const input = $input.first().json; 

try {
    const characterName = input.character_name;

    // --- Resolve Character ID directly from cache using input name ---
    const cachedId = await redis.hget('eve:name_to_id', characterName.toLowerCase());
    const characterId = cachedId ? parseInt(cachedId, 10) : null;

    if (!characterName) {
        throw new Error('Character name is required from prior steps.');
    }
    if (!characterId) { 
        throw new Error(`Character ID not found in cache for name: ${characterName}. Character Pull node may have failed or cache is empty.`);
    }

    console.log(`=== ZKILL RESILIENT PULL START for: ${characterName} (ID: ${characterId}) ===`);
    let zkillStats = { info: { id: characterId, name: characterName } };
    let recentKillmails = [];
    let needsAPI = false;
    let kmSource = 'unknown'; // To track where killmails came from

    // --- 1. Attempt to retrieve full stats object from cache ---
    const fullStatsKey = `intel:zkill:fullstats:${characterId}`;
    const cachedFullStats = await redis.get(fullStatsKey);

    if (cachedFullStats) {
        zkillStats = JSON.parse(cachedFullStats);
        lookupSource = 'Redis Cache (Full)';
        console.log(`✅ Cache HIT for full stats.`);
    } else {
        // --- 2. Fallback to local basic stats ---
        const localStatsKey = `intel:stats:character:${characterId}`;
        const localStatsRaw = await redis.hgetall(localStatsKey);

        if (Object.keys(localStatsRaw).length > 0) {
            zkillStats = {
                shipsDestroyed: parseInt(localStatsRaw.kill_count_total || 0, 10),
                shipsLost: parseInt(localStatsRaw.loss_count_total || 0, 10),
                valueDestroyed: parseFloat(localStatsRaw.value_destroyed || 0),
                valueLost: parseFloat(localStatsRaw.value_lost || 0),
                info: zkillStats.info,
                topLists: [], 
                groups: {}, 
            };
            lookupSource = 'Redis Cache (Partial)';
            needsAPI = true;
            console.log(`⚠️ Full cache MISS. Using partial local stats and flagging for API fill.`);
        } else {
            needsAPI = true;
            console.log(`❌ No local zKill data found. Flagging for full API fetch.`);
        }
    }

    // --- 3. External API Call (Conditional, for stats) ---
    if (needsAPI) {
        try {
            const statsUrl = `https://zkillboard.com/api/stats/characterID/${characterId}/`;
            const statsResponse = await axios.get(statsUrl, { 
                headers: { 'User-Agent': 'Alfred EVE Intel Tool' }, 
                timeout: 15000 
            });

            const apiStats = statsResponse.data;

            // Merge API stats over our partial stats
            zkillStats = {
                ...zkillStats,
                ...apiStats,
                info: apiStats.info || zkillStats.info,
            };

            await redis.set(fullStatsKey, JSON.stringify(zkillStats), 'EX', 3600); 
            lookupSource = (lookupSource.includes('Partial')) ? 'API Fill/Merge' : 'API Primary';
            console.log(`✅ API fetch succeeded. Data merged and full cache updated.`);

        } catch (apiError) {
            console.warn(`❌ External API fetch failed (${apiError.message}). Using available local data.`);
        }
    }

    // --- 4. Fetch Recent Killmails (3-STAGE FALLBACK) ---
    const killsKey = `intel:kills:character:${characterId}`;
    const lossesKey = `intel:losses:character:${characterId}`;
    const tempKey = `intel:temp:recent:${characterId}:${Math.floor(Math.random() * 10000)}`;

    let recentEventIds = [];

    try {
        // 4a. Try to merge local kills and losses
        console.log(`[KM PULL] Checking local keys: ${killsKey} and ${lossesKey}`);
        await redis.zunionstore(tempKey, 2, killsKey, lossesKey, 'AGGREGATE', 'MAX');
        await redis.expire(tempKey, 10); 
        recentEventIds = await redis.zrevrange(tempKey, 0, 24); // Get top 25

        if (recentEventIds && recentEventIds.length > 0) {
            // 4b. Fetch data for the merged IDs from *our* cache
            const killData = await redis.hmget('intel:kill:data', ...recentEventIds);
            recentKillmails = killData.filter(Boolean).map(JSON.parse);
            kmSource = 'Redis Cache (Merged K/L)';
            console.log(`✅ Retrieved ${recentKillmails.length} recent killmails from local index (merged K/L).`);
        } else {
            // 4c. Fallback to zKillboard API (if local keys are empty)
            console.log(`⚠️ No recent killmails in local index. Fetching from zKill API (/recent/)...`);
            try {
                const kmUrlRecent = `https://zkillboard.com/api/kills/characterID/${characterId}/recent/`;
                const kmResponseRecent = await axios.get(kmUrlRecent, {
                    headers: { 'User-Agent': 'Alfred EVE Intel Tool' },
                    timeout: 10000
                });

                if (Array.isArray(kmResponseRecent.data) && kmResponseRecent.data.length > 0) {
                    recentKillmails = kmResponseRecent.data.slice(0, 25); // Take top 25
                    kmSource = 'zKill API (Recent)';
                    console.log(`✅ Retrieved ${recentKillmails.length} recent killmails from zKill API (/recent/).`);
                } else {
                    // 4d. FINAL FALLBACK: Try the main zKill API endpoint (/limit/25/)
                    console.log(`⚠️ /recent/ endpoint was empty. Trying zKill API (/limit/25/)...`);
                    const kmUrlLimit = `https://zkillboard.com/api/kills/characterID/${characterId}/limit/25/`;
                    const kmResponseLimit = await axios.get(kmUrlLimit, {
                        headers: { 'User-Agent': 'Alfred EVE Intel Tool' },
                        timeout: 10000
                    });

                    if (Array.isArray(kmResponseLimit.data) && kmResponseLimit.data.length > 0) {
                        recentKillmails = kmResponseLimit.data; // Already limited
                        kmSource = 'zKill API (Limit 25)';
                        console.log(`✅ Retrieved ${recentKillmails.length} killmails from zKill API (/limit/25/).`);
                    } else {
                        kmSource = 'zKill API (All Empty)';
                        console.log('⚠️ zKill API returned no killmails for this character from any endpoint.');
                    }
                }
            } catch (kmError) {
                kmSource = 'API Error';
                console.warn(`❌ zKill API fetch for killmails failed: ${kmError.message}`);
            }
        }
    } catch (redisError) {
        console.error(`[KM PULL] Redis ZUNIONSTORE failed: ${redisError.message}.`);
        kmSource = 'API Fallback (Redis Error)';
        // In this case, we'd want to duplicate the API fallback logic here, but for now we'll just log.
    }

    // --- 5. Assemble Output ---
    const output = {
        ...input,
        data: {
            stats: zkillStats,
            recent_killmails: recentKillmails
        },
        zkill_source: lookupSource,
        killmail_source: kmSource,
        zkill_fetched_at: new Date().toISOString(),
    };

    console.log(`📊 Zkill data pulled. Final Source: ${lookupSource} | KM Source: ${kmSource}`);

    return [{ json: output }];

} catch (error) {
    console.error('❌ Zkill pull CRITICAL failure:', error.message);

    const safeInput = $input.first().json;
    const safeCharacterId = null;
    const safeCharacterName = safeInput.character_name || 'unknown';

    return [{ 
        json: { 
            ...safeInput,
            data: {
                stats: {
                    shipsDestroyed: 0,
                    shipsLost: 0,
                    info: { id: safeCharacterId, name: safeCharacterName },
                    topLists: [],
                    groups: {}
                },
                recent_killmails: []
            },
            zkill_error: error.message,
            zkill_source: 'critical_failure'
        } 
    }];
} finally {
    if (redis.status === 'ready') await redis.quit();
}

// Enhanced Input Validator - Handles Single OR Batch Character Intel
const input = $input.first().json;

console.log('=== ENHANCED INTEL SUBWORKFLOW INPUT VALIDATION ===');
console.log('Received input:', JSON.stringify(input, null, 2));

// Determine if this is single or batch processing
let characterNames = [];
let isBatchMode = false;

// Priority: character_names array takes precedence
if (input.character_names && Array.isArray(input.character_names)) {
  characterNames = input.character_names;
  isBatchMode = true;
  console.log(`📊 Batch mode detected: ${characterNames.length} characters`);
} else if (input.character_name && typeof input.character_name === 'string') {
  characterNames = [input.character_name];
  isBatchMode = false;
  console.log(`👤 Single mode detected: ${input.character_name}`);
} else {
  return [{
    json: {
      error: true,
      message: 'Missing character input. Provide either character_name (string) or character_names (array)',
      required_input: {
        character_name: 'string (single character)', 
        character_names: 'array (batch processing)'
      },
      received_input: input
    }
  }];
}

// Validate and clean character names
const cleanedNames = [];
const invalidNames = [];

for (const name of characterNames) {
  if (!name || typeof name !== 'string') {
    invalidNames.push(`Invalid name: ${name}`);
    continue;
  }

  const cleanName = name.trim();
  if (cleanName.length === 0) {
    invalidNames.push(`Empty name: "${name}"`);
    continue;
  }

  if (cleanName.length > 37) {
    invalidNames.push(`Name too long: "${cleanName}" (${cleanName.length} chars, max 37)`);
    continue;
  }

  cleanedNames.push(cleanName);
}

// Check for validation errors
if (cleanedNames.length === 0) {
  return [{
    json: {
      error: true,
      message: 'No valid character names found',
      invalid_names: invalidNames,
      received_input: input
    }
  }];
}

// Log validation warnings
if (invalidNames.length > 0) {
  console.warn(`⚠️ ${invalidNames.length} invalid names skipped:`, invalidNames);
}

// Check batch size limits
const MAX_BATCH_SIZE = 10; // Reasonable limit to prevent overload
if (cleanedNames.length > MAX_BATCH_SIZE) {
  return [{
    json: {
      error: true,
      message: `Batch size limit exceeded. Maximum ${MAX_BATCH_SIZE} characters, received ${cleanedNames.length}`,
      suggested_batches: Math.ceil(cleanedNames.length / MAX_BATCH_SIZE),
      received_input: input
    }
  }];
}

console.log(`✅ Input validated successfully:`);
console.log(`   - Mode: ${isBatchMode ? 'Batch' : 'Single'}`);
console.log(`   - Valid names: ${cleanedNames.length}`);
console.log(`   - Invalid names: ${invalidNames.length}`);
console.log(`   - Names: ${cleanedNames.join(', ')}`);

// Return validated input with batch metadata
return [{
  json: {
    // Processing configuration
    is_batch_mode: isBatchMode,
    character_names: cleanedNames,
    batch_size: cleanedNames.length,

    // For backward compatibility
    character_name: cleanedNames[0], // First name for single-mode compatibility

    // Validation metadata
    original_input: input,
    validation_timestamp: new Date().toISOString(),
    subworkflow_version: '2.1_batch_enabled',
    validation_summary: {
      total_requested: characterNames.length,
      valid_names: cleanedNames.length,
      invalid_names: invalidNames.length,
      skipped_names: invalidNames
    }
  }
}];

// AUGMENTED NODE (v4.4 - Combined Fixes)
// - FIX 1: Checks for capital usage in lifetime stats (`stats.groups`)
// - FIX 2: Falls back to lifetime `stats.labels` for security analysis if recent killmails are empty.
// - FIX 3: Lowered `isWhOperator` threshold from 0.5 (50%) to 0.3 (30%).

const Redis = require('ioredis');
let redis;

try {
  const input = $input.first().json;
  if (!input || !input.character_esi) {
    throw new Error('Input is missing critical ESI character data.');
  }

  redis = new Redis({ host: 'redis', port: 6379, db: 0, connectTimeout: 5000 });
  await redis.ping();

  console.log('[Final Assembly] Starting analysis for:', input.character_name);

  const characterId = input.character_id;
  // Use the killmails from the resilient fetcher (could be from Redis or API)
  const killmails = input.data.recent_killmails || [];
  // Use the stats from the resilient fetcher (could be from Redis or API)
  const stats = input.data.stats || { shipsDestroyed: 0, shipsLost: 0, groups: {} };

  // --- 1. SDE Enhancement (Resolving missing IDs from ESI data) ---
  const idsToResolve = new Set();
  if (input.corporation_esi.ceo_id) idsToResolve.add(input.corporation_esi.ceo_id);
  if (input.corporation_esi.home_station_id) idsToResolve.add(input.corporation_esi.home_station_id);
  if (input.alliance_esi.executor_corporation_id) idsToResolve.add(input.alliance_esi.executor_corporation_id);
  if (input.character_esi.race_id) idsToResolve.add(input.character_esi.race_id);
  if (input.character_esi.bloodline_id) idsToResolve.add(input.character_esi.bloodline_id);
  if (Array.isArray(input.corporation_history_esi)) {
      input.corporation_history_esi.forEach(rec => idsToResolve.add(rec.corporation_id));
  }

  // --- Pre-cache names we know we'll need from recent killmails ---
  // This avoids slow, individual lookups inside the analysis loop
  for (const km of killmails) {
      if (km.victim) {
          // zKill API uses shipTypeID, our cache uses ship_type_id
          idsToResolve.add(km.victim.shipTypeID || km.victim.ship_type_id);
          idsToResolve.add(km.victim.character_id);
      }
      if (km.attackers) {
          km.attackers.forEach(a => idsToResolve.add(a.ship_type_id || a.shipTypeID));
      }
      idsToResolve.add(km.solar_system_id);
  }
  idsToResolve.delete(undefined); // Clean up any undefined IDs
  idsToResolve.delete(null);

  let idNameMap = new Map();
  if (idsToResolve.size > 0) {
    const idArray = Array.from(idsToResolve).map(String); // Ensure all IDs are strings for redis
    const nameResults = await redis.hmget('eve:id_to_name', ...idArray);
    idNameMap = new Map(idArray.map((id, i) => [Number(id), nameResults[i] || `ID ${id}`])); // Store keys as numbers for lookup
  }
  console.log(`[Final Assembly] Resolved ${idNameMap.size} SDE/KM IDs from local cache.`);

  // Enhance ESI objects with resolved names
  const enhancedCharacter = {
    ...input.character_esi,
    race_name: idNameMap.get(input.character_esi.race_id),
    bloodline_name: idNameMap.get(input.character_esi.bloodline_id)
  };
  const enhancedCorporation = {
    ...input.corporation_esi,
    ceo_name: idNameMap.get(input.corporation_esi.ceo_id),
    home_station_name: idNameMap.get(input.corporation_esi.home_station_id)
  };
  const enhancedAlliance = {
    ...input.alliance_esi,
    executor_corporation_name: idNameMap.get(input.alliance_esi.executor_corporation_id)
  };
  const enhancedCorpHistory = Array.isArray(input.corporation_history_esi) 
    ? input.corporation_history_esi.map(rec => ({
        ...rec,
        corporation_name: idNameMap.get(rec.corporation_id)
      }))
    : [];

  // Pass the resolved names to the generator node, nested inside 'stats.info'
  // so the generator's "recent activity" loop can use it.
  if (stats.info) {
    stats.info.idNameMap = Object.fromEntries(idNameMap);
  } else {
    stats.info = { idNameMap: Object.fromEntries(idNameMap) };
  }

  // --- 2. Killmail-Based Analysis (Top Ships, Systems, Threat) ---
  const shipAnalysis = { kills: {}, losses: {} };
  const systemAnalysis = { kills: {} };
  const securityAnalysis = { highsec: 0, lowsec: 0, nullsec: 0, wormhole: 0 };
  let capitalUsage = false;
  const CAPITAL_CLASSES_BY_NAME = ['carrier', 'dreadnought', 'force_auxiliary', 'supercarrier', 'titan', 'capital_industrial', 'lancer_dreadnought'];
  const CAPITAL_CLASSES_BY_ZKILL_NAME = ['Carrier', 'Dreadnought', 'Force Auxiliary', 'Supercarrier', 'Titan', 'Capital Industrial Ship', 'Lancer Dreadnought'];

  // Helper function to get ship class from our ingested data OR zKill API data
  const getShipClass = (km) => {
    if (km.victim_ship_class) return km.victim_ship_class; // From our enriched data
    if (km.victim?.shipTypeID) {
        const name = idNameMap.get(km.victim.shipTypeID);
        if (name && CAPITAL_CLASSES_BY_ZKILL_NAME.includes(name)) {
            // This is imperfect but good for cap flagging
            return name.toLowerCase().replace(/ /g, '_');
        }
    }
    return 'unknown'; // Default
  };

  const systemDetailsCache = new Map();
  const hasRecentActivity = killmails.length > 0;

  if (hasRecentActivity) {
      console.log(`[Final Assembly] Analyzing ${killmails.length} recent killmails...`);
      for (const km of killmails) {
        const isLoss = (km.victim.character_id === characterId);

        if (isLoss) {
          const shipClass = getShipClass(km);
          shipAnalysis.losses[shipClass] = (shipAnalysis.losses[shipClass] || 0) + 1;
          if (CAPITAL_CLASSES_BY_NAME.includes(shipClass)) capitalUsage = true;

        } else {
          const attacker = km.attackers.find(a => a.character_id === characterId);
          if (!attacker) continue;

          let shipName = 'unknown';
          const shipTypeID = attacker.ship_type_id || attacker.shipTypeID;
          if(shipTypeID) {
            const name = idNameMap.get(shipTypeID);
            if (name) {
              shipName = name;
              if (CAPITAL_CLASSES_BY_ZKILL_NAME.includes(name)) capitalUsage = true;
            }
          }
          shipAnalysis.kills[shipName] = (shipAnalysis.kills[shipName] || 0) + 1;

          // Get system name
          let systemName = 'Unknown System';
          const solarSystemID = km.solar_system_id || km.solarSystemID;
          if(solarSystemID) {
            const name = idNameMap.get(solarSystemID);
            if (name) systemName = name;
          }
          systemAnalysis.kills[systemName] = (systemAnalysis.kills[systemName] || 0) + 1;

          // Get space type
          if (km.space_type) { // This field only exists on OUR cached killmails
             switch (km.space_type) {
              case 'highsec': securityAnalysis.highsec++; break;
              case 'lowsec': securityAnalysis.lowsec++; break;
              case 'nullsec': securityAnalysis.nullsec++; break;
              case 'wormhole': securityAnalysis.wormhole++; break;
            }
          } else if (solarSystemID) {
            // Fallback: Get security from system details
            let details = systemDetailsCache.get(solarSystemID);
            if (!details) {
                const detailsStr = await redis.hget('eve:system_details', solarSystemID);
                if (detailsStr) {
                    details = JSON.parse(detailsStr);
                    systemDetailsCache.set(solarSystemID, details);
                }
            }

            if (details) {
              if (details.securityClass === 'highsec') securityAnalysis.highsec++;
              else if (details.securityClass === 'lowsec') securityAnalysis.lowsec++;
              else if (details.securityClass === 'nullsec') securityAnalysis.nullsec++;
              else securityAnalysis.wormhole++; // Covers WH and others
            }
          }
        }
      }
  } else {
      console.log("[Final Assembly] No recent killmails found. Using LIFETIME stats for security analysis.");
      // --- FALLBACK LOGIC ---
      // Use the zKill lifetime stats as a fallback
      const locLabels = stats?.labels || {};
      securityAnalysis.highsec = locLabels['loc:highsec']?.shipsDestroyed || 0;
      securityAnalysis.lowsec = locLabels['loc:lowsec']?.shipsDestroyed || 0;
      securityAnalysis.nullsec = locLabels['loc:nullsec']?.shipsDestroyed || 0;
      securityAnalysis.wormhole = locLabels['loc:w-space']?.shipsDestroyed || 0;
      // --- END FALLBACK LOGIC ---
  }


  // --- LIFETIME CAPITAL CHECK ---
  // After checking recent KMs, check lifetime stats from zKill `stats.groups`
  if (!capitalUsage && stats.groups) {
      const capitalGroupIDs = [
          '30', // Titan
          '485', // Dreadnought
          '547', // Carrier
          '659', // Supercarrier
          '883', // Capital Industrial Ship
          '1538', // Force Auxiliary
          '4594' // Lancer Dreadnought
      ];

      for (const groupID of capitalGroupIDs) {
          if (stats.groups[groupID]) {
              // Check if they have *any* kills or losses with this group
              if ((stats.groups[groupID].shipsDestroyed || 0) > 0 || (stats.groups[groupID].shipsLost || 0) > 0) {
                  capitalUsage = true;
                  console.log(`[Final Assembly] Capital usage confirmed from LIFETIME stats (GroupID: ${groupID}).`);
                  break; // Found one, no need to check more
              }
          }
      }
  }
  // --- END LIFETIME CHECK ---


  // Convert maps to sorted arrays
  const formatAnalysis = (obj) => Object.entries(obj)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count);

  const topKillsShips = formatAnalysis(shipAnalysis.kills).slice(0, 5);
  const topLossesShips = formatAnalysis(shipAnalysis.losses).slice(0, 5);
  const topSystems = formatAnalysis(systemAnalysis.kills).slice(0, 10);

  // --- 3. Threat Assessment ---
  let threatLevel = 'Low';
  let reasons = [];

  const totalKills = stats.shipsDestroyed || 0;
  const totalLosses = stats.shipsLost || 0;
  const whKills = securityAnalysis.wormhole;
  // Use the sum of the analysis object for total activity
  const totalActivity = whKills + securityAnalysis.nullsec + securityAnalysis.lowsec + securityAnalysis.highsec;

  // --- THIS IS THE FIX ---
  // Lowered threshold from 0.5 to 0.3 (30%)
  const whPercentage = totalActivity > 0 ? (whKills / totalActivity) : 0;
  // Also require a minimum number of kills to be flagged, to avoid noise
  const isWhOperator = whPercentage >= 0.30 && totalKills > 10;
  // --- END FIX ---

  if (totalKills > 1000) reasons.push("High lifetime kill count (1000+)");
  if (capitalUsage) reasons.push("Capital ship usage detected (lifetime or recent)");
  // Updated reason text to be more accurate
  if (isWhOperator) reasons.push("Primarily a Wormhole operator (>= 30% activity)");

  if (isWhOperator && capitalUsage) threatLevel = 'Critical';
  else if (totalKills > 2000 || (isWhOperator && totalKills > 100)) threatLevel = 'High';
  else if (totalKills > 500) threatLevel = 'Medium';
  else if (totalKills === 0 && totalLosses === 0) threatLevel = 'Very Low';

  if (reasons.length === 0) reasons.push("No specific threat indicators found.");

  // --- 4. Assemble Final Object ---
  const finalAssembly = {
    // Core Info
    character_name: input.character_name,
    character_id: characterId,
    lookup_timestamp: input.validation_timestamp,
    is_batch_mode: input.is_batch_mode || false,

    // Enhanced ESI Data
    character: enhancedCharacter,
    corporation: enhancedCorporation,
    alliance: enhancedAlliance,
    corporation_history: enhancedCorpHistory,

    // Stats (from hybrid fetcher)
    stats: stats,
    data_source: {
      stats: input.zkill_source,
      killmails: input.killmail_source
    },

    // Analysis (from real killmails OR lifetime stats)
    analysis: {
      threat_level: threatLevel,
      threat_reasons: reasons,
      capital_usage_detected: capitalUsage,
      is_wormhole_operator: isWhOperator,
      top_kill_ships: topKillsShips,
      top_loss_ships: topLossesShips,
      top_systems: topSystems,
      security_analysis: securityAnalysis,
      source: hasRecentActivity ? 'recent_killmail_analysis' : 'lifetime_stats_fallback'
    },

    // Raw Data (for debugging or deep dives)
    recent_killmails: killmails.slice(0, 25) // Return top 25 most recent
  };

  console.log(`[Final Assembly] Analysis complete. Threat Level: ${threatLevel}`);

  return [{ json: finalAssembly }];

} catch (error) {
  console.error('❌ Final Intel Assembly failed:', error.message, error.stack);
  const errorOutput = { 
    error_message: error.message, 
    character_name: $input.first().json.character_name || 'unknown', 
    stack: error.stack 
  };
  return [{ json: errorOutput }];
} finally {
  if (redis) await redis.quit();
}
